####### # Setup #######
Context('Numeric'); @xy = random_subset(4, -5..-1,1..5); @x = map {$_ + list_random(-3..-1,1..3)/4} ((@xy)[0,1]); @y = map {$_ + list_random(-3..-1,1..3)/4} ((@xy)[2,3]); @p = map {Point($x[$_], $y[$_])} (0,1); $gt = GraphTool("{point,$p[0]}", "{point,$p[1]}")->with( availableTools => ['PointTool'], bBox => [-6,6,6,-6], snapSizeX => 1/4, snapSizeY => 1/4, showInStatic => 0, showCoordinateHints => 0, );
############################# # Exercise Group Introduction #############################
BEGIN_PGML Make a Cartesian plot with the indicated points marked.
END_PGML
###### # Body ######
BEGIN_PGML [`[$p[0]], [$p[1]]`]
[_]{$gt}{1}
END_PGML
